894		/**
895		 * @brief Skip over a number of bytes.
896		 *
897		 * Skips over a number of bytes from the stream. This should be used
898		 * if the stream holds data that you don't care about but don't want
899		 * to have to read it to another buffer to access data beyond it.
900		 * 
901		 * @param length The number of bytes to skip.
902		 */
903		void skip(const size_type length) {
904			STREAM_READ_BOUNDS_ENFORCE(length, void());
905			buffer_.skip(length);
906		}
