1015		/**
1016		 * @return Pointer to stream's underlying buffer.
1017		 */
1018		const buf_type* buffer() const {
1019			return &buffer_;
1020		}
1021	
1022		/**
1023		 * @return Pointer to stream's underlying buffer.
1024		 */
1025		buf_type* buffer() {
