124	// Returns true if there's any overlap between source and destination ranges
125	[[maybe_unused]]
126	static inline bool region_overlap(const void* src, std::size_t src_len,
127	                                  const void* dst, std::size_t dst_len) {
128		const auto src_beg = std::bit_cast<std::uintptr_t>(src);
129		const auto src_end = src_beg + src_len;
130		const auto dst_beg = std::bit_cast<std::uintptr_t>(dst);
131		const auto dst_end = dst_beg + dst_len;
132		return src_beg < dst_end && dst_beg < src_end;
133	}
