7	#pragma once
8	
9	#include <hexi/pmc/buffer.h>
10	#include <hexi/pmc/buffer_read_adaptor.h>
11	#include <hexi/pmc/buffer_write_adaptor.h>
12	#include <hexi/concepts.h>
13	#include <ranges>
14	
15	namespace hexi::pmc {
16	
17	template<byte_oriented buf_type, bool allow_optimise  = true>
18	requires std::ranges::contiguous_range<buf_type>
19	class buffer_adaptor final : public buffer_read_adaptor<buf_type>,
20	                             public buffer_write_adaptor<buf_type>,
21	                             public buffer {
22		void conditional_clear() {
23			if(buffer_read_adaptor<buf_type>::read_ptr() == buffer_write_adaptor<buf_type>::write_ptr()) {
24				clear();
25			}
26		}
27	
28	public:
29		explicit buffer_adaptor(buf_type& buffer)
30			: buffer_read_adaptor<buf_type>(buffer),
31			  buffer_write_adaptor<buf_type>(buffer) {}
32	
33		explicit buffer_adaptor(buf_type& buffer, init_empty_t)
34			: buffer_read_adaptor<buf_type>(buffer, init_empty),
35			  buffer_write_adaptor<buf_type>(buffer, init_empty) {}
36	
37		/**
38		 * @brief Reads a number of bytes to the provided buffer.
39		 * 
40		 * @param destination The buffer to copy the data to.
41		 */
42		template<typename T>
43		void read(T* destination) {
44			buffer_read_adaptor<buf_type>::read(destination);
45	
46			if constexpr(allow_optimise) {
47				conditional_clear();
48			}
49		}
50	
51		/**
52		 * @brief Reads a number of bytes to the provided buffer.
53		 * 
54		 * @param destination The buffer to copy the data to.
55		 * @param length The number of bytes to read into the buffer.
56		 */
57		void read(void* destination, std::size_t length) override {
58			buffer_read_adaptor<buf_type>::read(destination, length);
59	
60			if constexpr(allow_optimise) {
61				conditional_clear();
62			}
63		};
64	
65		/**
66		 * @brief Write data to the container.
67		 * 
68		 * @param source Pointer to the data to be written.
69		 */
70		void write(const auto& source) {
71			buffer_write_adaptor<buf_type>::write(source);
72		};
73	
74		/**
75		 * @brief Write provided data to the container.
76		 * 
77		 * @param source Pointer to the data to be written.
78		 * @param length Number of bytes to write from the source.
79		 */
80		void write(const void* source, std::size_t length) override {
81			buffer_write_adaptor<buf_type>::write(source, length);
82		};
83	
84		void copy(auto* destination) const {
85			buffer_read_adaptor<buf_type>::copy(destination);
86		};
87	
88		/**
89		 * @brief Copies a number of bytes to the provided buffer but without advancing
90		 * the read cursor.
91		 * 
92		 * @param destination The buffer to copy the data to.
93		 * @param length The number of bytes to copy.
94		 */
95		void copy(void* destination, std::size_t length) const override {
96			buffer_read_adaptor<buf_type>::copy(destination, length);
97		};
98	
99		/**
100		 * @brief Skip over a number of bytes.
101		 *
102		 * Skips over a number of bytes from the container. This should be used
103		 * if the container holds data that you don't care about but don't want
104		 * to have to read it to another buffer to access data beyond it.
105		 * 
106		 * @param length The number of bytes to skip.
107		 */
108		void skip(std::size_t length) override {
109			buffer_read_adaptor<buf_type>::skip(length);
110	
111			if constexpr(allow_optimise) {
112				conditional_clear();
113			}
114		};
115	
116		/**
117		 * @brief Retrieves a reference to the specified index within the container.
118		 * 
119		 * @param index The index within the container.
120		 * 
121		 * @return A reference to the value at the specified index.
122		 */
123		const std::byte& operator[](const std::size_t index) const override { 
124			return buffer_read_adaptor<buf_type>::operator[](index); 
125		};
126	
127		/**
128		 * @brief Retrieves a reference to the specified index within the container.
129		 * 
130		 * @param index The index within the container.
131		 * 
132		 * @return A reference to the value at the specified index.
133		 */
134		std::byte& operator[](const std::size_t index) override {
135			const auto offset = buffer_read_adaptor<buf_type>::read_offset();
136			auto buffer = buffer_write_adaptor<buf_type>::storage();
137			return reinterpret_cast<std::byte*>(buffer + offset)[index];
138		}
139	
140		/**
141		 * @brief Reserves a number of bytes within the container for future use.
142		 * 
143		 * @param length The number of bytes that the container should reserve.
144		 */
145		void reserve(std::size_t length) override {
146			buffer_write_adaptor<buf_type>::reserve(length);
147		};
148	
149		/**
150		 * @brief Determines whether this container can write seek.
151		 * 
152		 * @return Whether this container is capable of write seeking.
153		 */
154		bool can_write_seek() const override { 
155			return buffer_write_adaptor<buf_type>::can_write_seek();
156		};
157	
158		/**
159		 * @brief Performs write seeking within the container.
160		 * 
161		 * @param direction Specify whether to seek in a given direction or to absolute seek.
162		 * @param offset The offset relative to the seek direction or the absolute value
163		 * when using absolute seeking.
164		 */
165		void write_seek(buffer_seek direction, std::size_t offset) override {
166			buffer_write_adaptor<buf_type>::write_seek(direction, offset);
167		};
168	
169		/**
170		 * @brief Returns the size of the container.
171		 * 
172		 * @return The number of bytes of data available to read within the stream.
173		 */
174		std::size_t size() const override { 
175			return buffer_read_adaptor<buf_type>::size(); 
176		};
177	
178		/**
179		 * @brief Whether the container is empty.
180		 * 
181		 * @return Returns true if the container is empty (has no data to be read).
182		 */
183		[[nodiscard]]
184		bool empty() const override {
185			return buffer_read_adaptor<buf_type>::read_offset()
186				== buffer_write_adaptor<buf_type>::write_offset();
187		}
188	
189		/**
190		 * @brief Attempts to locate the provided value within the container.
191		 * 
192		 * @param value The value to locate.
193		 * 
194		 * @return The position of value or npos if not found.
195		 */
196		std::size_t find_first_of(std::byte val) const override { 
197			return buffer_read_adaptor<buf_type>::find_first_of(val);
198		}
199	
200		/**
201		 * @brief Clears the underlying buffer, resetting both the read
202		 * and write cursors.
203		 */
204		void clear() {
205			buffer_read_adaptor<buf_type>::clear();
206			buffer_write_adaptor<buf_type>::clear();
207		}
208	};
209	
210	} // pmc, hexi
