```cpp
#include <hexi/hexi.h>
#include <vector>
#include <cstdint>
#include <span>

struct DataResult {
    uint8_t data_type;
    std::vector<uint32_t> int_items;
    std::vector<float> float_items;
};

DataResult preview_and_read_data(const std::span<const uint8_t> buffer) {
    DataResult result{};

    // Create a mutable copy of the buffer for buffer_adaptor
    std::vector<uint8_t> buffer_copy(buffer.begin(), buffer.end());

    // Create buffer_adaptor from the buffer
    hexi::buffer_adaptor<std::vector<uint8_t>> adaptor(buffer_copy);

    // Check if buffer has at least 1 byte for data_type
    if (adaptor.size() < 1) {
        return result;
    }

    // Preview the first byte (data_type) without advancing the read pointer
    result.data_type = adaptor[0];

    // Check if buffer has enough data for header (1 byte data_type + 4 bytes item_count)
    if (adaptor.size() < 5) {
        return result;
    }

    // Create binary_stream to read the data
    hexi::binary_stream<hexi::buffer_adaptor<std::vector<uint8_t>>> stream(adaptor);

    // Read data_type (uint8_t)
    uint8_t data_type;
    stream >> data_type;

    // Read item_count (uint32_t)
    uint32_t item_count;
    stream >> item_count;

    // Check if stream is in good state
    if (!stream.good()) {
        return result;
    }

    // Calculate required size for items
    size_t item_size = (data_type == 0) ? sizeof(uint32_t) : sizeof(float);
    size_t required_size = item_size * item_count;

    // Check if buffer has enough data
    if (stream.size() < required_size) {
        return result;
    }

    // Read items based on data type
    if (data_type == 0) {
        // Read integers (uint32_t)
        result.int_items.resize(item_count);
        for (uint32_t i = 0; i < item_count; ++i) {
            stream >> result.int_items[i];
        }
    } else if (data_type == 1) {
        // Read floats
        result.float_items.resize(item_count);
        for (uint32_t i = 0; i < item_count; ++i) {
            stream >> result.float_items[i];
        }
    }

    return result;
}
```

