#include <hexi/hexi.h>
#include <vector>
#include <cstdint>

bool write_data_with_check(std::vector<uint8_t>& buffer, uint32_t header, const std::vector<uint32_t>& items) {
    // Create a buffer_adaptor initialized as empty (write position starts at 0)
    hexi::buffer_adaptor<std::vector<uint8_t>> adaptor(buffer, hexi::init_empty);

    // Calculate required space:
    // - header: sizeof(uint32_t)
    // - container prefix (item count): sizeof(uint32_t)
    // - items data: items.size() * sizeof(uint32_t)
    const auto required_space = sizeof(uint32_t) + sizeof(uint32_t) + (items.size() * sizeof(uint32_t));

    // Check if we have enough space available
    if (adaptor.free() < required_space) {
        return false;
    }

    // Create binary_stream from the buffer_adaptor for writing
    hexi::binary_stream stream(adaptor);

    // Write header
    stream << header;

    // Write items container (automatically writes size prefix + data)
    stream << hexi::prefixed(items);

    // Check if write was successful
    return stream.good();
}
```

