361		 * @brief Resets both the read and write cursors back to the beginning
362		 * of the buffer.
363		 * 
364		 * @note The underlying buffer will not be cleared but should be treated
365		 * as thought it has been.
366		 */
367		void clear() {
368			read_ = write_ = 0;
369		}
