29	TEST(binary_stream, message_read_limit) {
30		std::array<std::uint8_t, 14> ping {
31			0x00, 0x0C, 0xDC, 0x01, 0x00, 0x00, 0x01,
32			0x00, 0x00, 0x00, 0xF4, 0x01, 0x00, 0x00
33		};
34	
35		// write the ping packet data twice to the buffer
36		hexi::dynamic_buffer<32> buffer;
37		buffer.write(ping.data(), ping.size());
38		buffer.write(ping.data(), ping.size());
39	
40		// read one packet back out (reuse the ping array)
41		hexi::binary_stream stream(buffer, ping.size());
42		ASSERT_EQ(stream.read_limit(), ping.size());
43		ASSERT_NO_THROW(stream.get(ping.data(), ping.size()))
44			<< "Failed to read packet back from stream";
45	
46		// attempt to read past the stream message bound
47		ASSERT_THROW(stream.get(ping.data(), ping.size()), hexi::stream_read_limit)
48			<< "Message boundary was not respected";
49		ASSERT_EQ(stream.state(), hexi::stream_state::read_limit_err)
50			<< "Unexpected stream state";
51	}
