#include <hexi/hexi.h>
#include <cstdint>
#include <span>
#include <vector>

struct PacketHeader {
    uint32_t magic;
    uint16_t version;
    uint16_t flags;
};

PacketHeader read_header_with_span(const std::span<const uint8_t> buffer) {
    // Create a vector from the span to use with buffer_adaptor
    std::vector<uint8_t> vec(buffer.begin(), buffer.end());

    // Create a buffer_adaptor to manage the buffer
    hexi::buffer_adaptor adaptor(vec);

    // Get the read pointer - demonstrates pointer access
    const uint8_t* read_ptr = adaptor.read_ptr();

    // Check available data - demonstrates size checking
    if (adaptor.size() < sizeof(PacketHeader)) {
        // Return a default-initialized header if not enough data
        return PacketHeader{0, 0, 0};
    }

    // Create a binary_stream for zero-copy operations
    hexi::binary_stream stream(adaptor);

    // Get a zero-copy view of the header using span
    auto header_span = stream.span<const uint8_t>(sizeof(PacketHeader));

    // Extract header fields from the span
    PacketHeader header;

    // Read magic (uint32_t - 4 bytes)
    std::memcpy(&header.magic, header_span.data(), sizeof(uint32_t));

    // Read version (uint16_t - 2 bytes)
    std::memcpy(&header.version, header_span.data() + 4, sizeof(uint16_t));

    // Read flags (uint16_t - 2 bytes)
    std::memcpy(&header.flags, header_span.data() + 6, sizeof(uint16_t));

    return header;
}
