72		 * 
73		 * @note The destination buffer must not overlap with the underlying buffer
74		 * being used by the buffer_adaptor.
75		 * 
76		 * @param[out] destination The buffer to copy the data to.
77		 * @param length The number of bytes to read into the buffer.
78		 */
79		void read(void* destination, size_type length) {
80			assert(destination);
81			copy(destination, length);
82			read_ += length;
83	
84			if constexpr(space_optimise) {
85				if(read_ == write_) {
86					read_ = write_ = 0;
87				}
88			}
89		}
90	
