#include <hexi/allocators/block_allocator.h>
#include <cstdint>
#include <iostream>

// Note: push() and pop() are private, but we can observe their behavior
// through allocate() and deallocate() operations
template<size_t element_count = 10>
void demonstrate_block_allocator_behavior() {
    // Create a block_allocator that can hold 'element_count' integers
    // This internally calls initialise_free_list() which uses push() to build the free list
    hexi::block_allocator<int, element_count> allocator;

    std::cout << "=== Block Allocator Free List Demonstration ===" << std::endl;
    std::cout << "Capacity: " << element_count << " elements" << std::endl;

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "\nInitial state (all blocks in free list):" << std::endl;
    std::cout << "  Storage active: " << allocator.storage_active_count << std::endl;
    std::cout << "  Heap active: " << allocator.new_active_count << std::endl;
    std::cout << "  Total active: " << allocator.active_count << std::endl;
#endif

    // Step 1: Allocate several blocks
    // Each allocate() internally calls pop() to remove the head from the free list
    std::cout << "\n--- Allocating 5 blocks ---" << std::endl;
    int* blocks[5];
    for (size_t i = 0; i < 5; ++i) {
        blocks[i] = allocator.allocate(static_cast<int>(i * 10));
        std::cout << "Allocated block " << i << " with value: " << *blocks[i] << std::endl;
    }

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "\nAfter allocations:" << std::endl;
    std::cout << "  Storage active: " << allocator.storage_active_count << std::endl;
    std::cout << "  Heap active: " << allocator.new_active_count << std::endl;
    std::cout << "  Total active: " << allocator.active_count << std::endl;
    std::cout << "  Total allocs: " << allocator.total_allocs << std::endl;
#endif

    // Step 2: Deallocate some blocks (they go back to free list via push())
    // Each deallocate() internally calls push() to add the block back to the head
    std::cout << "\n--- Deallocating blocks 1 and 3 (LIFO order) ---" << std::endl;
    allocator.deallocate(blocks[1]);
    std::cout << "Deallocated block 1" << std::endl;
    allocator.deallocate(blocks[3]);
    std::cout << "Deallocated block 3" << std::endl;

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "\nAfter partial deallocations:" << std::endl;
    std::cout << "  Storage active: " << allocator.storage_active_count << std::endl;
    std::cout << "  Total active: " << allocator.active_count << std::endl;
    std::cout << "  Total deallocs: " << allocator.total_deallocs << std::endl;
#endif

    // Step 3: Reallocate - will get blocks in LIFO order (block 3, then block 1)
    std::cout << "\n--- Reallocating 2 blocks (demonstrates LIFO/stack behavior) ---" << std::endl;
    int* new_block1 = allocator.allocate(99);
    std::cout << "Reallocated block with value: " << *new_block1 << std::endl;

    int* new_block2 = allocator.allocate(88);
    std::cout << "Reallocated block with value: " << *new_block2 << std::endl;

    // Step 4: Clean up remaining blocks
    std::cout << "\n--- Cleaning up remaining blocks ---" << std::endl;
    allocator.deallocate(blocks[0]);
    allocator.deallocate(blocks[2]);
    allocator.deallocate(blocks[4]);
    allocator.deallocate(new_block1);
    allocator.deallocate(new_block2);

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "\nFinal state (all blocks returned to free list):" << std::endl;
    std::cout << "  Storage active: " << allocator.storage_active_count << std::endl;
    std::cout << "  Total active: " << allocator.active_count << std::endl;
    std::cout << "  Total allocs: " << allocator.total_allocs << std::endl;
    std::cout << "  Total deallocs: " << allocator.total_deallocs << std::endl;
#endif

