44	/**
45	 * Basic fixed-size block stack allocator that preallocates a slab of memory
46	 * capable of holding a compile-time determined number of elements.
47	 * When constructed, a linked list of chunks is built within the slab and
48	 * each allocation request will take the head node. Since the allocations
49	 * are fixed-size, the list does not need to be traversed for a suitable
50	 * size. Deallocations place the chunk as the new head (LIFO).
51	 *
52	 * If the preallocated slab runs out of chunks, it will fall back to using the
53	 * system allocator rather than allocating additional slabs. This means sizing
54	 * the initial allocation correctly is important for maximum performance, so
55	 * it's better to be pessimistic. This is a server application and RAM is cheap. :)
56	 *
57	 * PagePolicy: 'lock' requests that the OS does not page out the memory slab to disk.
58	 *
59	 * ThreadPolicy: 'same_thread' triggers an assert if an allocated object
60	 * is deallocated from a different thread. Used by the TLS allocator, since
61	 * implementing the functionality there is messier (and slower).
62	 */
63	template<typename _ty, 
64		std::size_t _elements,
65		std::derived_from<no_validate_dealloc> ValidatePolicy = no_validate_dealloc>
66	requires gt_zero<_elements> && sizeof_gte<_ty, free_block>
67	class block_allocator {
68		using tid_type = std::conditional_t<
69			std::is_same_v<ValidatePolicy, validate_dealloc>, std::thread::id, std::monostate
70		>;
71	
72		struct mem_block {
73			_ty obj;
74	
75			struct {
76				[[no_unique_address]] tid_type thread_id;
77				bool using_new;
78			} meta;
79		};
80	
81		static constexpr auto block_size = sizeof(mem_block);
82	
83		free_block* head_ = nullptr;
84		[[no_unique_address]] tid_type thread_id_;
85		std::array<char, block_size * _elements> storage_;
86	
87		void initialise_free_list() {
88			auto storage = storage_.data();
89	
90			for(std::size_t i = 0; i < _elements; ++i) {
91				auto block = reinterpret_cast<free_block*>(storage + (block_size * i));
92				push(block);
93			}
94		}
95	
96		inline void push(free_block* block) {
97			assert(block);
98			block->next = head_;
99			head_ = block;
100		}
101	
102		[[nodiscard]] inline free_block* pop() {
103			if(!head_) {
104				return nullptr;
105			}
106	
107			auto block = head_;
108			head_ = block->next;
109			return block;
110		}
111	
112	public:
113	#ifdef HEXI_DEBUG_ALLOCATORS
114		std::size_t storage_active_count = 0;
115		std::size_t new_active_count = 0;
116		std::size_t active_count = 0;
117		std::size_t total_allocs = 0;
118		std::size_t total_deallocs = 0;
119	#endif
120	
121		block_allocator() requires std::same_as<ValidatePolicy, validate_dealloc>
122			: thread_id_(std::this_thread::get_id()) {
123			initialise_free_list();
124		}
125	
126		block_allocator() {
127			initialise_free_list();
128		}
129	
130		template<typename ...Args>
131		[[nodiscard]] inline _ty* allocate(Args&&... args) {
132			auto block = reinterpret_cast<mem_block*>(pop());
133	
134			if(block) [[likely]] {
135	#ifdef HEXI_DEBUG_ALLOCATORS
136				++storage_active_count;
137	#endif
138				block->meta.using_new = false;
139			} else {
140	#ifdef HEXI_DEBUG_ALLOCATORS
141				++new_active_count;
142	#endif
143				block = new mem_block;
144				block->meta.using_new = true;
145			}
146	
147			if constexpr(std::is_same_v<ValidatePolicy, validate_dealloc>) {
148				block->meta.thread_id = thread_id_;
149			}
150	
151	#ifdef HEXI_DEBUG_ALLOCATORS
152			++total_allocs;
153			++active_count;
154	#endif
155			return new (&block->obj) _ty(std::forward<Args>(args)...);
156		}
157	
158		inline void deallocate(_ty* t) {
159			assert(t);
160			auto block = reinterpret_cast<mem_block*>(t);
161	
162			if constexpr(std::is_same_v<ValidatePolicy, validate_dealloc>) {
163				assert(block->meta.thread_id == thread_id_
164					&& "thread policy violation or clobbered block");
165			}
166	
167			if(block->meta.using_new) [[unlikely]] {
168	#ifdef HEXI_DEBUG_ALLOCATORS
169				--new_active_count;
170	#endif
171				t->~_ty();
172				delete block;
173			} else {
174	#ifdef HEXI_DEBUG_ALLOCATORS
