Perfect! Now I understand the `intrusive_storage` API. Let me implement the three functions:

1. **`preview_data_without_consuming`**: Should use the `copy()` method which reads data without advancing the read pointer
2. **`check_buffer_status`**: Should use `size()` for readable data and `free()` for available space
3. **`reset_buffer`**: Should use `clear()` to reset both offsets

Here's the complete implementation:

```cpp
#include <hexi/detail/intrusive_storage.h>
#include <vector>
#include <cstdint>

template<size_t block_size = 1024>
std::vector<uint8_t> preview_data_without_consuming(const hexi::detail::intrusive_storage<block_size>& storage, size_t bytes_to_preview) {
    // Create a vector to hold the preview data
    std::vector<uint8_t> preview_buffer(bytes_to_preview);

    // Use the copy() method which doesn't advance the read pointer
    size_t bytes_copied = storage.copy(preview_buffer.data(), bytes_to_preview);

    // Resize the vector to the actual number of bytes copied
    preview_buffer.resize(bytes_copied);

    return preview_buffer;
}

template<size_t block_size = 1024>
struct BufferStatus {
    size_t readable_size;
    size_t free_space;
};

template<size_t block_size = 1024>
BufferStatus<block_size> check_buffer_status(const hexi::detail::intrusive_storage<block_size>& storage) {
    BufferStatus<block_size> status;

    // Use size() to get the number of readable bytes
    status.readable_size = storage.size();

    // Use free() to get the available free space
    status.free_space = storage.free();

    return status;
}

template<size_t block_size = 1024>
void reset_buffer(hexi::detail::intrusive_storage<block_size>& storage) {
    // Use clear() to reset both read and write offsets
    storage.clear();
}
