std::vector<uint8_t> read_file_data(const std::filesystem::path& file_path, size_t bytes_to_read) {
    hexi::file_buffer file(file_path);

    if (!file) {
        return {}; // Return empty vector on error
    }

    // Ensure we don't read more than available
    size_t available = file.size();
    size_t to_read = (bytes_to_read < available) ? bytes_to_read : available;

    std::vector<uint8_t> buffer(to_read);
    file.read(buffer.data(), to_read);

    if (!file) {
        return {}; // Return empty vector on read error
    }

    return buffer;
}

std::vector<uint8_t> preview_file_data(const std::filesystem::path& file_path, size_t bytes_to_preview) {
    hexi::file_buffer file(file_path);

    if (!file) {
        return {}; // Return empty vector on error
    }

    // Ensure we don't preview more than available
    size_t available = file.size();
    size_t to_preview = (bytes_to_preview < available) ? bytes_to_preview : available;

    std::vector<uint8_t> buffer(to_preview);
    file.copy(buffer.data(), to_preview);

    if (!file) {
        return {}; // Return empty vector on copy error
    }

    return buffer;
