#include <hexi/static_buffer.h>
#include <vector>
#include <cstdint>

template<size_t buffer_size = 1024>
void write_data_to_buffer(hexi::static_buffer<std::byte, buffer_size>& buffer, const std::vector<uint8_t>& data) {
    // Write the data from the vector to the static_buffer
    // The write method takes a pointer to the source data and the length
    buffer.write(data.data(), data.size());
}

template<size_t buffer_size = 1024>
std::vector<uint8_t> read_data_from_buffer(hexi::static_buffer<std::byte, buffer_size>& buffer, size_t bytes_to_read) {
    // Create a vector to hold the read data
    std::vector<uint8_t> result(bytes_to_read);

    // Read the data from the static_buffer into the vector
    // The read method takes a pointer to the destination and the length
    buffer.read(result.data(), bytes_to_read);

    return result;
}
```

**Explanation:**

1. **`write_data_to_buffer`**: This function writes data from a `std::vector<uint8_t>` to the `static_buffer`. It uses the `buffer.write()` method, passing:
   - `data.data()` - pointer to the vector's data
   - `data.size()` - number of bytes to write

2. **`read_data_from_buffer`**: This function reads data from the `static_buffer` into a new `std::vector<uint8_t>`. It:
   - Creates a vector of the requested size
   - Uses `buffer.read()` to read the data, passing the vector's data pointer and the number of bytes to read
   - Returns the populated vector

The `static_buffer` handles the internal read/write cursors automatically, so consecutive reads will advance the position in the buffer.

