26	#define STREAM_READ_BOUNDS_ENFORCE(read_size, ret_var)            \
27		if(state() != stream_state::ok) [[unlikely]] {                \
28			return ret_var;                                           \
29		}                                                             \
30	                                                                  \
31		enforce_read_bounds(read_size);                               \
32		                                                              \
33		if(!allow_throw()) {                                          \
34			if(state() != stream_state::ok) [[unlikely]] {            \
35				return ret_var;                                       \
36			}                                                         \
37		}
38	
39	#define SAFE_READ(dest, read_size, ret_var)                       \
40		STREAM_READ_BOUNDS_ENFORCE(read_size, ret_var)                \
41		buffer_.read(dest, read_size);
42	
43	class binary_stream_reader : virtual public stream_base {
44		buffer_read& buffer_;
45		std::size_t total_read_;
46		const std::size_t read_limit_;
47	
48		inline void enforce_read_bounds(const std::size_t read_size) {
49			if(read_size > buffer_.size()) [[unlikely]] {
50				set_state(stream_state::buff_limit_err);
51	
52				if(allow_throw()) {
53					HEXI_THROW(buffer_underrun(read_size, total_read_, buffer_.size()));
54				}
55	
56				return;
57			}
58	
59			if(read_limit_) {
60				const auto max_read_remaining = read_limit_ - total_read_;
61	
62				if(read_size > max_read_remaining) [[unlikely]] {
63					set_state(stream_state::read_limit_err);
64	
65					if(allow_throw()) {
66						HEXI_THROW(stream_read_limit(read_size, total_read_, read_limit_));
67					}
68	
69					return;
70				}
71			}
72	
73			total_read_ += read_size;
74		}
75	
76		template<typename container_type, typename count_type>
77		void read_container(container_type& container, const count_type count) {
78			using cvalue_type = typename container_type::value_type;
79	
80			if constexpr(!memcpy_read<container_type, binary_stream_reader>) {
81				container.clear();
82			}
83	
84			if constexpr(has_reserve<container_type>) {
85				container.reserve(count);
86			}
87	
88			if constexpr(memcpy_read<container_type, binary_stream_reader>) {
89				container.resize(count);
90	
91				const auto bytes = count * sizeof(cvalue_type);
92				SAFE_READ(container.data(), bytes, void());
93			} else {
94				for(count_type i = 0; i < count; ++i) {
95					cvalue_type value;
96					*this >> value;
97					container.emplace_back(std::move(value));
98				}
99			}
100		}
