24	namespace hexi::pmc {
25	
26	using namespace detail;
27	
28	class binary_stream_writer : virtual public stream_base {
29		buffer_write& buffer_;
30		std::size_t total_write_;
31	
32		inline void write(const void* data, const std::size_t size) {
33			HEXI_TRY {
34				if(state() == stream_state::ok) [[likely]] {
35					buffer_.write(data, size);
36					total_write_ += size;
37				}
38			} HEXI_CATCH(...) {
39				set_state(stream_state::buff_write_err);
40	
41				if(allow_throw()) {
42					HEXI_THROW();
43				}
44			}
45		}
46	
47		template<typename container_type>
48		void write_container(container_type& container) {
49			using cvalue_type = typename container_type::value_type;
50	
51			if constexpr(memcpy_write<container_type, binary_stream_writer>) {
52				const auto bytes = container.size() * sizeof(cvalue_type);
53				write(container.data(), bytes);
54			} else {
55				for(auto& element : container) {
56					*this << element;
57				}
58			}
59		}
60	
61	public:
62		explicit binary_stream_writer(buffer_write& source)
63			: stream_base(source),
64			  buffer_(source),
65			  total_write_(0) {}
66	
67		explicit binary_stream_writer(buffer_write& source, no_throw_t)
68			: stream_base(source, false),
69			  buffer_(source),
70			  total_write_(0) {}
71	
72		binary_stream_writer(binary_stream_writer&& rhs) noexcept
73			: stream_base(rhs),
74			  buffer_(rhs.buffer_), 
75			  total_write_(rhs.total_write_) {
76			rhs.total_write_ = static_cast<std::size_t>(-1);
77			rhs.set_state(stream_state::invalid_stream);
78		}
79	
80		binary_stream_writer& operator=(binary_stream_writer&&) = delete;
81		binary_stream_writer& operator=(const binary_stream_writer&) = delete;
82		binary_stream_writer(const binary_stream_writer&) = delete;
83	
84		/**
85		 * @brief Serialises an object that provides a serialise function:
86		 * void serialise(auto& stream);
87		 * 
88		 * @param object The object to be serialised.
89		 */
90		void serialise(auto&& object) {
91			stream_write_adaptor adaptor(*this);
92			object.serialise(adaptor);
93		}
94	
95		/**
96		 * @brief Serialises an object that provides a serialise function:
97		 * void serialise(auto& stream);
98		 * 
99		 * @param data The object to be serialised.
100		 * 
101		 * @return Reference to the current stream.
102		 */
103		template<typename T>
104		requires has_serialise<T, binary_stream_writer>
105		binary_stream_writer& operator<<(T& data) {
106			serialise(data);
107			return *this;
108		}
109	
110		/**
111		 * @brief Serialises an object that provides a serialise function:
112		 * auto& operator<<(auto& stream);
113		 * 
114		 * @param data The object to be serialised.
115		 * 
116		 * @return Reference to the current stream.
117		 */
118		binary_stream_writer& operator<<(has_shl_override<binary_stream_writer> auto&& data) {
119			return *this << data;
120		}
121	
122		/**
123		 * @brief Serialises an arithmetic type with the requested byte order.
124		 * 
125		 * @param adaptor An endian adaptor.
126		 * 
127		 * @return Reference to the current stream.
128		 */
129		template<std::derived_from<endian::adaptor_tag_t> endian_func>
130		binary_stream_writer& operator<<(endian_func adaptor) {
131			const auto converted = adaptor.to();
132			write(&converted, sizeof(converted));
133			return *this;
134		}
135	
136		/**
137		 * @brief Serialises a POD type.
138		 * 
139		 * @note This overload will not be selected for types that provide a
140		 * user-defined serialise function.
141		 * 
142		 * @param data The object to serialise.
143		 * 
144		 * @return Reference to the current stream.
145		 */
146		template<pod T>
147		requires (!has_shl_override<T, binary_stream_writer>)
148		binary_stream_writer& operator<<(const T& data) {
149			write(&data, sizeof(data));
150			return *this;
151		}
152	
153		template<typename T>
154		requires std::is_same_v<std::decay_t<T>, std::string_view>
155		binary_stream_writer& operator<<(null_terminated<T> adaptor) {
156			assert(adaptor->find_first_of('\0') == adaptor->npos);
157			write(adaptor->data(), adaptor->size());
158			const char terminator = '\0';
159			write(&terminator, 1);
160			return *this;
161		}
162	
163		/**
164		 * @brief Serialises a string_view as a null terminated string.
165		 * 
166		 * @tparam T The string type.
167		 * @param adaptor null_terminated adaptor that will instruct the stream to write
168		 * a null terminated string with no prefix.
169		 * 
170		 * @return Reference to the current stream.
171		 */
172		template<typename T>
173		requires std::is_same_v<std::decay_t<T>, std::string>
174		binary_stream_writer& operator<<(null_terminated<T> adaptor) {
175			assert(adaptor->find_first_of('\0') == adaptor->npos);
176			write(adaptor->data(), adaptor->size() + 1); // yes, the standard allows this
177			return *this;
178		}
179	
180		/**
181		 * @brief Serialises a string, string_view or any type providing data()
182		 * and a size() member functions.
183		 * 
184		 * @tparam T The type.
185		 * @param adaptor raw adaptor referencing the type to be serialised.
186		 * 
187		 * @return Reference to the current stream.
188		 */
189		template<typename T>
190		binary_stream_writer& operator<<(raw<T> adaptor) {
191			write(adaptor->data(), adaptor->size());
192			return *this;
193		}
194	
195		/**
196		 * @brief Serialises an std::string_view with a fixed-length prefix.
197		 * 
198		 * @param string std::string_view to be serialised with a prefix.
199		 * 
200		 * @return Reference to the current stream.
201		 */
202		binary_stream_writer& operator<<(std::string_view string) {
203			return *this << prefixed(string);
204		}
205	
206		/**
207		 * @brief Serialises an std::string with a fixed-length prefix.
208		 * 
209		 * @param string std::string to be serialised with a prefix.
210		 * 
211		 * @return Reference to the current stream.
212		 */
213		binary_stream_writer& operator<<(const std::string& string) {
214			return *this << prefixed(string);
215		}
216	
217		/**
218		 * @brief Serialises a C-style string.
219		 * 
220		 * @param data string to be serialised.
221		 * 
222		 * @note The null terminator for this string will also be written. It will
223		 * not be prefixed.
224		 * 
225		 * @return Reference to the current stream.
226		 */
227		binary_stream_writer& operator<<(const char* data) {
228			assert(data);
229			const auto len = std::strlen(data);
230			write(data, len + 1); // include terminator
231			return *this;
232		}
233	
234		binary_stream_writer& operator<<(const is_iterable auto& data) {
235			write_container(data);
236			return *this;
237		}
238	
239		/**
240		 * @brief Serialises an iterable container.
241		 * 
242		 * @tparam T The iterable container type.
243		 * @param adaptor The container to be serialised.
244		 * 
245		 * @note A fixed-length prefix representing the number of elements in the
246		 * container will be written before the elements.
247		 * 
248		 * @return Reference to the current stream.
249		 */
250		template<is_iterable T>
251		binary_stream_writer& operator<<(prefixed<T> adaptor) {
252			const auto count = endian::native_to_little(static_cast<std::uint32_t>(adaptor->size()));
253			write(&count, sizeof(count));
254			write_container(adaptor.str);
255			return *this;
256		}
257	
258		/**
259		 * @brief Serialises an iterable container.
260		 * 
261		 * @tparam T The iterable container type.
262		 * @param adaptor The container to be serialised.
263		 * 
264		 * @note A variable-length prefix representing the number of elements in the
265		 * container will be written before the elements.
266		 * 
267		 * @return Reference to the current stream.
268		 */
269		template<is_iterable T>
270		binary_stream_writer& operator<<(prefixed_varint<T> adaptor) {
271			varint_encode(*this, adaptor->size());
272			write_container(adaptor.str);
273			return *this;
274		}
275	
276		/**
277		 * @brief Writes a contiguous range to the stream.
278		 * 
279		 * @param data The contiguous range to be written to the stream.
280		 */
281		template<std::ranges::contiguous_range range>
282		void put(range& data) {
283			const auto write_size = data.size() * sizeof(typename range::value_type);
284			write(data.data(), write_size);
285		}
286	
287		/**
288		 * @brief Writes a the provided value to the stream.
289		 * 
290		 * @param data The value to be written to the stream.
291		 */
292		void put(const arithmetic auto& data) {
293			write(&data, sizeof(data));
294		}
295	
296		/**
297		 * @brief Writes data to the stream.
298		 * 
299		 * @param data The element to be written to the stream.
300		 */
301		template<std::derived_from<endian::adaptor_tag_t> endian_func>
302		void put(const endian_func& adaptor) {
303			const auto swapped = adaptor.to();
304			write(&swapped, sizeof(swapped));
305		}
306	
307		/**
308		 * @brief Writes bytes from the provided buffer to the stream.
309		 * 
310		 * @tparam T POD type.
311		 * @param data Pointer to the buffer from which data will be copied to the stream.
312		 * @param count The number of elements to write.
313		 */
314		template<pod T>
315		void put(const T* data, std::size_t count) {
316			assert(data);
317			const auto write_size = count * sizeof(T);
318			write(data, write_size);
319		}
320	
321		/**
322		 * @brief Writes the data from the iterator range to the stream.
323		 * 
324		 * @tparam It The iterator type.
325		 * @param begin Iterator to the beginning of the data.
326		 * @param end Iterator to the end of the data.
327		 */
328		template<typename It>
329		void put(It begin, const It end) {
330			for(auto it = begin; it != end; ++it) {
331				*this << *it;
332			}
333		}
334	
335		/**
336		 * @brief Allows for writing a provided byte value a specified number of times to
337		 * the stream.
338		 * 
339		 * @tparam size The number of bytes to generate.
340		 * @param value The byte value that will fill the specified number of bytes.
341		 */
342		template<std::size_t size>
343		void fill(const std::uint8_t value) {
344			const auto filled = generate_filled<size>(value);
345			write(filled.data(), filled.size());
346		}
347	
348		/**  Misc functions **/ 
349	
350		/**
351		 * @brief Determines whether this container can write seek.
352		 * 
353		 * @return Whether this container is capable of write seeking.
354		 */
355		bool can_write_seek() const {
356			return buffer_.can_write_seek();
357		}
358	
359		/**
360		 * @brief Performs write seeking within the container.
361		 * 
362		 * @param direction Specify whether to seek in a given direction or to absolute seek.
363		 * @param offset The offset relative to the seek direction or the absolute value
364		 * when using absolute seeking.
365		 */
366		void write_seek(const stream_seek direction, const std::size_t offset) {
367			if(direction == stream_seek::sk_stream_absolute) {
368				if(offset >= total_write_) {
369					buffer_.write_seek(buffer_seek::sk_forward, offset - total_write_);
370				} else {
371					buffer_.write_seek(buffer_seek::sk_backward, total_write_ - offset);
372				}
373	
374				total_write_ = offset;
375			} else {
376				buffer_.write_seek(static_cast<buffer_seek>(direction), offset);
377			}
378		}
379	
380		/**
381		 * @brief Returns the size of the container.
382		 * 
383		 * @return The number of bytes of data available to read within the stream.
384		 */
385		std::size_t size() const {
386			return buffer_.size();
387		}
388	
389		/**
390		 * @brief Whether the container is empty.
391		 * 
392		 * @return Returns true if the container is empty (has no data to be read).
393		 */
394		[[nodiscard]]
395		bool empty() const {
396			return buffer_.empty();
397		}
398	
399		/**
400		 * @return The total number of bytes written to the stream.
401		 */
402		std::size_t total_write() const {
403			return total_write_;
404		}
405	
406		/** 
407		 * @brief Get a pointer to the buffer write interface.
408		 *
409		 * @return Pointer to the buffer write interface. 
410		 */
411		buffer_write* buffer() {
412			return &buffer_;
413		}
414	
415		/** 
416		 * @brief Get a pointer to the buffer write interface.
417		 *
418		 * @return Pointer to the buffer write interface. 
419		 */
420		const buffer_write* buffer() const {
421			return &buffer_;
422		}
423	};
424	
425	} // pmc, hexi
