7	#pragma once
8	
9	#include <hexi/pmc/stream_base.h>
10	#include <hexi/pmc/buffer_read.h>
11	#include <hexi/concepts.h>
12	#include <hexi/endian.h>
13	#include <hexi/exception.h>
14	#include <hexi/shared.h>
15	#include <hexi/stream_adaptors.h>
16	#include <ranges>
17	#include <string>
18	#include <cassert>
19	#include <cstddef>
20	#include <cstdint>
21	
22	namespace hexi::pmc {
23	
24	using namespace detail;
25	
26	#define STREAM_READ_BOUNDS_ENFORCE(read_size, ret_var)            \
27		if(state() != stream_state::ok) [[unlikely]] {                \
28			return ret_var;                                           \
29		}                                                             \
30	                                                                  \
31		enforce_read_bounds(read_size);                               \
32		                                                              \
33		if(!allow_throw()) {                                          \
34			if(state() != stream_state::ok) [[unlikely]] {            \
35				return ret_var;                                       \
36			}                                                         \
37		}
38	
39	#define SAFE_READ(dest, read_size, ret_var)                       \
40		STREAM_READ_BOUNDS_ENFORCE(read_size, ret_var)                \
41		buffer_.read(dest, read_size);
42	
43	class binary_stream_reader : virtual public stream_base {
44		buffer_read& buffer_;
45		std::size_t total_read_;
46		const std::size_t read_limit_;
47	
48		inline void enforce_read_bounds(const std::size_t read_size) {
49			if(read_size > buffer_.size()) [[unlikely]] {
50				set_state(stream_state::buff_limit_err);
51	
52				if(allow_throw()) {
53					HEXI_THROW(buffer_underrun(read_size, total_read_, buffer_.size()));
54				}
55	
56				return;
57			}
58	
59			if(read_limit_) {
60				const auto max_read_remaining = read_limit_ - total_read_;
61	
62				if(read_size > max_read_remaining) [[unlikely]] {
63					set_state(stream_state::read_limit_err);
64	
65					if(allow_throw()) {
66						HEXI_THROW(stream_read_limit(read_size, total_read_, read_limit_));
67					}
68	
69					return;
70				}
71			}
72	
73			total_read_ += read_size;
74		}
75	
76		template<typename container_type, typename count_type>
77		void read_container(container_type& container, const count_type count) {
78			using cvalue_type = typename container_type::value_type;
79	
80			if constexpr(!memcpy_read<container_type, binary_stream_reader>) {
81				container.clear();
82			}
83	
84			if constexpr(has_reserve<container_type>) {
85				container.reserve(count);
86			}
87	
88			if constexpr(memcpy_read<container_type, binary_stream_reader>) {
89				container.resize(count);
90	
91				const auto bytes = count * sizeof(cvalue_type);
92				SAFE_READ(container.data(), bytes, void());
93			} else {
94				for(count_type i = 0; i < count; ++i) {
95					cvalue_type value;
96					*this >> value;
97					container.emplace_back(std::move(value));
98				}
99			}
100		}
101	
102	public:
103		explicit binary_stream_reader(buffer_read& source, std::size_t read_limit = 0)
104			: stream_base(source),
105			  buffer_(source),
106			  total_read_(0),
107			  read_limit_(read_limit) {}
108	
109		explicit binary_stream_reader(buffer_read& source, no_throw_t, std::size_t read_limit = 0)
110			: stream_base(source, false),
111			  buffer_(source),
112			  total_read_(0),
113			  read_limit_(read_limit) {}
114	
115		binary_stream_reader(binary_stream_reader&& rhs) noexcept
116			: stream_base(rhs),
117			  buffer_(rhs.buffer_),
118			  total_read_(rhs.total_read_),
119			  read_limit_(rhs.read_limit_) {
120			rhs.total_read_ = static_cast<std::size_t>(-1);
121			rhs.set_state(stream_state::invalid_stream);
122		}
123	
124		binary_stream_reader& operator=(binary_stream_reader&&) = delete;
125		binary_stream_reader& operator=(const binary_stream_reader&) = delete;
126		binary_stream_reader(const binary_stream_reader&) = delete;
127	
128		/**
129		 * @brief Deserialises an object that provides a deserialise function:
130		 * void serialise(auto& stream);
131		 * 
132		 * @param[out] object The object to be deserialised.
133		 */
134		void deserialise(auto& object) {
135			stream_read_adaptor adaptor(*this);
136			object.serialise(adaptor);
137		}
138	
139		/**
140		 * @brief Deserialises an object that provides a deserialise function:
141		 * void serialise(auto& stream);
142		 * 
143		 * @param[out] data The object to be serialised.
144		 * 
145		 * @return Reference to the current stream.
146		 */
147		template<typename T>
148		requires has_deserialise<T, binary_stream_reader>
149		binary_stream_reader& operator>>(T& data) {
150			deserialise(data);
151			return *this;
152		}
153	
154		/**
155		 * @brief Deserialises a string that was previously written with a
156		 * fixed-length prefix.
