```cpp
#include <hexi/shared.h>
#include <hexi/pmc/buffer_adaptor.h>
#include <hexi/pmc/binary_stream_writer.h>
#include <hexi/pmc/binary_stream_reader.h>
#include <vector>
#include <cstdint>

using namespace hexi::detail;

template<typename T>
std::size_t encode_varint(hexi::pmc::binary_stream_writer& writer, T value) {
    return varint_encode<T>(writer, value);
}

template<typename T>
T decode_varint(hexi::pmc::binary_stream_reader& reader) {
    return varint_decode<T>(reader);
}

template<typename T>
bool encode_decode_roundtrip(T original_value) {
    // Create a buffer to hold the encoded data
    std::vector<std::byte> buffer;

    // Create a buffer adaptor for writing
    hexi::pmc::buffer_adaptor write_adaptor(buffer, hexi::init_empty);

    // Create a binary stream writer
    hexi::pmc::binary_stream_writer writer(write_adaptor);

    // Encode the value
    encode_varint(writer, original_value);

    // Create a buffer adaptor for reading
    hexi::pmc::buffer_adaptor read_adaptor(buffer);

    // Create a binary stream reader
    hexi::pmc::binary_stream_reader reader(read_adaptor);

    // Decode the value
    T decoded_value = decode_varint<T>(reader);

    // Compare the original and decoded values
    return original_value == decoded_value;
}
```

## Explanation:

1. **`encode_varint`**: This function wraps the Hexi library's `varint_encode` function from `hexi::detail`. It takes a `binary_stream_writer` and a value, encodes the value using varint encoding, and returns the number of bytes written.

2. **`decode_varint`**: This function wraps the Hexi library's `varint_decode` function. It takes a `binary_stream_reader` and returns the decoded value of type `T`.

3. **`encode_decode_roundtrip`**: This function verifies the correctness of varint encoding/decoding by:
   - Creating a `std::vector<std::byte>` buffer
   - Creating a `buffer_adaptor` initialized as empty for writing
   - Using a `binary_stream_writer` to encode the original value
   - Creating another `buffer_adaptor` for reading from the same buffer
   - Using a `binary_stream_reader` to decode the value
   - Comparing the decoded value with the original value

The implementation leverages Hexi's existing varint encoding/decoding functionality available in `hexi/shared.h` and properly uses the PMC (Packet Message Container) stream abstraction layer for efficient binary serialization.

