#include <hexi/exception.h>
#include <hexi/pmc/binary_stream.h>
#include <hexi/pmc/buffer_adaptor.h>
#include <vector>
#include <cstdint>

struct ReadLimitInfo {
    std::size_t read_size;
    std::size_t total_read;
    std::size_t read_limit;
    bool occurred;
};

ReadLimitInfo catch_stream_read_limit() {
    try {
        throw; // Re-throw the current exception
    } catch (const hexi::stream_read_limit& e) {
        return ReadLimitInfo{
            e.read_size,
            e.total_read,
            e.read_limit,
            true
        };
    } catch (...) {
        // Not a stream_read_limit exception
        return ReadLimitInfo{0, 0, 0, false};
    }
}

ReadLimitInfo safe_read_with_limit_check(hexi::pmc::binary_stream& stream, void* destination, std::size_t length) {
    try {
        stream.read(destination, length);
        // Read succeeded, no exception occurred
        return ReadLimitInfo{0, 0, 0, false};
    } catch (const hexi::stream_read_limit& e) {
        // stream_read_limit exception caught
        return ReadLimitInfo{
            e.read_size,
            e.total_read,
            e.read_limit,
            true
        };
    }
}
```

**Explanation:**

1. **`catch_stream_read_limit()`**: This function is designed to be called from within a catch block where an exception has already been thrown. It uses `throw;` to re-throw the current exception, then catches it if it's a `stream_read_limit` exception and extracts the three member variables (`read_size`, `total_read`, `read_limit`). The `occurred` field is set to `true` if the exception was successfully caught.

2. **`safe_read_with_limit_check()`**: This function attempts to read `length` bytes from the stream into the `destination` buffer. If the read succeeds without throwing an exception, it returns a `ReadLimitInfo` with `occurred` set to `false`. If a `stream_read_limit` exception is thrown, it catches it and extracts the exception's information into the `ReadLimitInfo` struct with `occurred` set to `true`.

