116			: stream_base(rhs),
117			  buffer_(rhs.buffer_),
118			  total_read_(rhs.total_read_),
119			  read_limit_(rhs.read_limit_) {
120			rhs.total_read_ = static_cast<std::size_t>(-1);
121			rhs.set_state(stream_state::invalid_stream);
122		}
