963		 * @brief Performs write seeking within the stream.
964		 * 
965		 * @param direction Specify whether to seek in a given direction or to absolute seek.
966		 * @param offset The offset relative to the seek direction or the absolute value
967		 * when using absolute seeking.
968		 */
969		void write_seek(const stream_seek direction, const offset_type offset)
970		requires(seekable<buf_type> && writeable<buf_type>) {
971			if(direction == stream_seek::sk_stream_absolute) {
972				if(offset >= total_write_) {
973					buffer_.write_seek(buffer_seek::sk_forward, offset - total_write_);
974				} else {
975					buffer_.write_seek(buffer_seek::sk_backward, total_write_ - offset);
976				}
977	
978				total_write_ = offset;
979			} else {
980				buffer_.write_seek(static_cast<buffer_seek>(direction), offset);
981			}
