std::vector<uint8_t> serialize_compact_packet(const CompactPacket& packet) {
    // Create a buffer to hold the serialized data
    std::vector<uint8_t> buffer;

    // Create a buffer adaptor with init_empty to start with an empty buffer
    hexi::buffer_adaptor adaptor(buffer, hexi::init_empty);

    // Create a binary stream for writing
    hexi::binary_stream stream(adaptor);

    // Serialize packet_id as uint32_t
    stream << packet.packet_id;

    // Serialize tags vector with prefixed_varint for compact encoding
    stream << hexi::prefixed_varint(packet.tags);

    // Serialize data string with prefixed_varint for compact encoding
    stream << hexi::prefixed_varint(packet.data);

    return buffer;
}

CompactPacket deserialize_compact_packet(const std::span<const uint8_t> buffer) {
    CompactPacket packet;

    // Create a mutable copy of the buffer data for the adaptor
    std::vector<uint8_t> buffer_copy(buffer.begin(), buffer.end());

    // Create a buffer adaptor
    hexi::buffer_adaptor adaptor(buffer_copy);

    // Create a binary stream for reading
    hexi::binary_stream stream(adaptor);

    // Deserialize packet_id
    stream >> packet.packet_id;

    // Deserialize tags vector with prefixed_varint
    stream >> hexi::prefixed_varint(packet.tags);

    // Deserialize data string with prefixed_varint
    stream >> hexi::prefixed_varint(packet.data);

    return packet;
}
