25	class buffer_read_adaptor : public buffer_read {
26		buf_type& buffer_;
27	
28	public:
29		buffer_read_adaptor(buf_type& buffer)
30			: buffer_(buffer) {
31			write_ = buffer_.size();
32		}
33	
34		buffer_read_adaptor(buf_type& buffer, init_empty_t)
35			: buffer_(buffer) {}
36	
37		/**
38		 * @brief Reads a number of bytes to the provided buffer.
39		 * 
40		 * @note The destination buffer must not overlap with the underlying buffer
41		 * being used by the buffer_adaptor.
42		 * 
43		 * @tparam T The destination type.
44		 * @param[out] destination The buffer to copy the data to.
45		 */
46		template<typename T>
47		void read(T* destination) {
48			read(destination, sizeof(T));
49		}
50	
51		/**
52		 * @brief Reads a number of bytes to the provided buffer.
53		 *
54		 * @note The destination buffer must not overlap with the underlying buffer
55		 * being used by the buffer_adaptor.
56		 * 
57		 * @param destination The buffer to copy the data to.
58		 * @param length The number of bytes to read into the buffer.
59		 */
60		void read(void* destination, std::size_t length) override {
61			assert(destination && !region_overlap(buffer_.data(), buffer_.size(), destination, length));
62			std::memcpy(destination, buffer_.data() + read_, length);
63			read_ += length;
64		}
65	
66		/**
67		 * @brief Copies a number of bytes to the provided buffer but without advancing
68		 * the read cursor.
69		 * 
70		 * @param[out] destination The buffer to copy the data to.
71		 */
72		template<typename T>
73		void copy(T* destination) const {
74			copy(destination, sizeof(T));
75		}
76	
77		/**
78		 * @brief Copies a number of bytes to the provided buffer but without advancing
79		 * the read cursor.
80		 * 
81		 * @note The destination buffer must not overlap with the underlying buffer
82		 * being used by the buffer_adaptor.
83		 * 
84		 * @param[out] destination The buffer to copy the data to.
85		 * @param length The number of bytes to copy.
86		 */
87		void copy(void* destination, std::size_t length) const override {
88			assert(destination && !region_overlap(buffer_.data(), buffer_.size(), destination, length));
89			std::memcpy(destination, buffer_.data() + read_, length);
90		}
91	
92		/**
93		 * @brief Skip over a number of bytes.
94		 *
95		 * Skips over a number of bytes from the container. This should be used
96		 * if the container holds data that you don't care about but don't want
97		 * to have to read it to another buffer to access data beyond it.
98		 * 
99		 * @param length The number of bytes to skip.
100		 */
101		void skip(std::size_t length) override {
102			read_ += length;
103		}
104	
105		/**
106		 * @brief Returns the size of the container.
107		 * 
108		 * @note The value returned may be higher than the total number of bytes
109		 * that can be read from this stream, if a read limit was set during
110		 * construction. Use read_max() to determine how many bytes can be
111		 * read from this stream.
112		 * 
113		 * @return The number of bytes of data available to read within the stream.
114		 */
115		std::size_t size() const override {
116			return write_ - read_;
117		}
118	
119		/**
120		 * @brief Whether the container is empty.
121		 * 
122		 * @return Returns true if the container is empty (has no data to be read).
123		 */
124		[[nodiscard]]
125		bool empty() const override {
126			return read_ == write_;
127		}
128	
129		/**
130		 * @brief Retrieves a reference to the specified index within the container.
131		 * 
132		 * @param index The index within the container.
133		 * 
134		 * @return A reference to the value at the specified index.
135		 */
136		const std::byte& operator[](const std::size_t index) const override {
137			return reinterpret_cast<const std::byte*>(buffer_.data() + read_)[index];
138		}
139	
140		/**
141		 * @return Pointer to the data available for reading.
142		 */
143		auto read_ptr() const {
144			return buffer_.data() + read_;
145		}
146	
147		/**
148		 * @return The current read offset.
149		 */
150		auto read_offset() const {
151			return read_;
152		}
153	
154		/**
155		 * @brief Attempts to locate the provided value within the container.
156		 * 
157		 * @param value The value to locate.
158		 * 
159		 * @return The position of value or npos if not found.
160		 */
161		std::size_t find_first_of(std::byte val) const override {
162			const auto data = read_ptr();
163	
164			for(std::size_t i = 0, j = size(); i < j; ++i) {
165				if(static_cast<std::byte>(data[i]) == val) {
166					return i;
167				}
168			}
169	
170			return npos;
171		}
172	
173		/*
174		 * @brief Resets both the read and write cursors back to the beginning
175		 * of the buffer.
176		 * 
177		 * @note The underlying buffer will not be cleared but should be treated
178		 * as thought it has been.
179		 */
180		void clear() {
181			read_ = 0;
182	
183			if constexpr(has_clear<buf_type>) {
184				buffer_.clear();
185			}
186		}
187	};
