#include <hexi/pmc/buffer_read_adaptor.h>
#include <hexi/pmc/buffer_write_adaptor.h>
#include <vector>
#include <cstdint>

std::vector<uint8_t> write_and_read_data(const std::vector<uint8_t>& input_data) {
    // Create a buffer to hold the data
    std::vector<uint8_t> buffer;

    // Create a buffer_write_adaptor with init_empty to start writing from the beginning
    hexi::pmc::buffer_write_adaptor<std::vector<uint8_t>> writer(buffer, hexi::pmc::init_empty);

    // Check available space before writing (free() returns buffer.size() - write_offset)
    // Since we start empty, free() will initially be 0, but write() will auto-resize

    // Write the input data to the buffer
    writer.write(input_data.data(), input_data.size());

    // Now create a buffer_read_adaptor to read the data back
    hexi::pmc::buffer_read_adaptor<std::vector<uint8_t>> reader(buffer);

    // Check the readable size
    std::size_t readable_size = reader.size();

    // Create output vector and read the data back
    std::vector<uint8_t> output_data(readable_size);
    reader.read(output_data.data(), readable_size);

    return output_data;
}

std::vector<uint8_t> peek_data_without_advancing(const std::vector<uint8_t>& buffer_data, std::size_t peek_size) {
    // Create a mutable copy since the adaptor requires a non-const reference
    std::vector<uint8_t> buffer_copy = buffer_data;

    // Create a buffer_read_adaptor
    hexi::pmc::buffer_read_adaptor<std::vector<uint8_t>> reader(buffer_copy);

    // Use read_ptr() to get a pointer to the current read position
    const auto* read_position = reader.read_ptr();

    // Use copy() to peek at data without moving the read cursor
    std::vector<uint8_t> peeked_data(peek_size);
    reader.copy(peeked_data.data(), peek_size);

    // Verify that read_ptr() hasn't moved after copy()
    // (it should still point to the same position)

    // Now use read() to actually consume the data
    std::vector<uint8_t> consumed_data(peek_size);
    reader.read(consumed_data.data(), peek_size);

    // Return the peeked data (which should be identical to consumed_data)
    return peeked_data;
}
```

