Now I have a good understanding of the Hexi library's API. Let me implement the three functions:

```cpp
#include <hexi/hexi.h>
#include <hexi/endian.h>
#include <vector>
#include <cstdint>
#include <span>

struct ProtocolPacket {
    uint32_t message_id;
    std::vector<uint16_t> data_values;
    uint32_t checksum;
};

std::vector<uint8_t> serialize_protocol_packet(const ProtocolPacket& packet) {
    // Create a buffer and stream for writing
    hexi::vector_buffer buffer;
    hexi::binary_stream stream(buffer);

    // Convert and write message_id from native to big-endian
    uint32_t message_id_be = hexi::endian::native_to_big(packet.message_id);
    stream.write(&message_id_be, sizeof(message_id_be));

    // Write the count of data_values (also in big-endian)
    uint32_t count_be = hexi::endian::native_to_big(static_cast<uint32_t>(packet.data_values.size()));
    stream.write(&count_be, sizeof(count_be));

    // Convert each element in data_values to big-endian and write
    std::vector<uint16_t> data_values_be;
    data_values_be.reserve(packet.data_values.size());
    for (const auto& value : packet.data_values) {
        data_values_be.push_back(hexi::endian::native_to_big(value));
    }
    stream.write_container(data_values_be);

    // Convert and write checksum from native to big-endian
    uint32_t checksum_be = hexi::endian::native_to_big(packet.checksum);
    stream.write(&checksum_be, sizeof(checksum_be));

    return buffer.data();
}

ProtocolPacket deserialize_protocol_packet(const std::span<const uint8_t> buffer) {
    // Create a read-only buffer view and stream
    hexi::buffer_adaptor<const std::span<const uint8_t>> buf_adaptor(buffer);
    hexi::binary_stream stream(buf_adaptor);

    ProtocolPacket packet;

    // Read message_id and convert from big-endian to native
    uint32_t message_id_be;
    stream.get(&message_id_be, 1);
    packet.message_id = hexi::endian::big_to_native(message_id_be);

    // Read count of data_values and convert from big-endian to native
    uint32_t count_be;
    stream.get(&count_be, 1);
    uint32_t count = hexi::endian::big_to_native(count_be);

    // Read data_values using read_container
    std::vector<uint16_t> data_values_be;
    stream.read_container(data_values_be, count);

    // Convert each element from big-endian to native
    packet.data_values.reserve(count);
    for (const auto& value_be : data_values_be) {
        packet.data_values.push_back(hexi::endian::big_to_native(value_be));
    }

    // Read checksum and convert from big-endian to native
    uint32_t checksum_be;
    stream.get(&checksum_be, 1);
    packet.checksum = hexi::endian::big_to_native(checksum_be);

    return packet;
}

struct ProtocolHeader {
    uint32_t message_id;
};

ProtocolHeader extract_protocol_header(const std::span<const uint8_t> buffer) {
    // Create a read-only buffer view and stream
    hexi::buffer_adaptor<const std::span<const uint8_t>> buf_adaptor(buffer);
    hexi::binary_stream stream(buf_adaptor);

    ProtocolHeader header;

    // Use span to get a zero-copy view of the first 4 bytes (message_id)
    auto message_id_span = stream.span<uint32_t>(1);

    // Convert the message_id from big-endian to native
    header.message_id = hexi::endian::big_to_native(message_id_span[0]);

    // Note: skip is already called by span(), so no need to skip again

    return header;
}
```

The implementation:

1. **`serialize_protocol_packet`**: Creates a vector buffer and binary stream, then converts each field from native to big-endian before writing. For the vector of data_values, I create a temporary big-endian copy and use `write_container`.

2. **`deserialize_protocol_packet`**: Creates a read-only buffer adaptor and stream, reads each field, and converts from big-endian to native. Uses `read_container` to read the vector, then converts each element individually.

3. **`extract_protocol_header`**: Uses the `span` method for zero-copy access to the first 4 bytes, converts from big-endian to native. The `span` method automatically advances the stream position.

