94			} else if constexpr(std::is_same_v<type, double>) {
95				value = std::bit_cast<type>(std::byteswap(std::bit_cast<std::uint64_t>(value)));
96			} else {
97				value = std::byteswap(value);
98			}
99		}
100	}
101	
102	constexpr void little_to_native_inplace(arithmetic auto& value) {
103		conditional_reverse_inplace<std::endian::little, std::endian::native>(value);
104	}
105	
106	constexpr void big_to_native_inplace(arithmetic auto& value) {
107		conditional_reverse_inplace<std::endian::big, std::endian::native>(value);
108	}
