338		/**
339		 * @brief Serialises an std::string_view with a fixed-length prefix.
340		 * 
341		 * @param string std::string_view to be serialised with a prefix.
342		 * 
343		 * @return Reference to the current stream.
344		 */
345		binary_stream& operator<<(std::string_view string) requires writeable<buf_type> {
346			return *this << prefixed(string);
347		}
348	
349		/**
350		 * @brief Serialises an std::string with a fixed-length prefix.
351		 * 
352		 * @param string std::string to be serialised with a prefix.
353		 * 
354		 * @return Reference to the current stream.
355		 */
356		binary_stream& operator<<(const std::string& string) requires writeable<buf_type> {
357			return *this << prefixed(string);
358		}
359	
360		/**
361		 * @brief Serialises a C-style string.
362		 * 
363		 * @param data string to be serialised.
364		 * 
365		 * @note The null terminator for this string will also be written. It will
366		 * not be prefixed.
367		 * 
368		 * @return Reference to the current stream.
369		 */
370		binary_stream& operator<<(const char* data) requires writeable<buf_type> {
371			assert(data);
372			const auto len = std::strlen(data);
373			write(data, len + 1); // include terminator
374			return *this;
375		}
376	
377		binary_stream& operator<<(const is_iterable auto& data) requires writeable<buf_type> {
378			write_container(data);
379			return *this;
380		}
381	
382		/**
383		 * @brief Serialises an iterable container.
384		 * 
385		 * @tparam T The iterable container type.
386		 * @param adaptor The container to be serialised.
387		 * 
388		 * @note A fixed-length prefix representing the number of elements in the
389		 * container will be written before the elements.
390		 * 
391		 * @return Reference to the current stream.
392		 */
393		template<is_iterable T>
394		binary_stream& operator<<(prefixed<T> adaptor) requires writeable<buf_type> {
395			const auto count = static_cast<std::uint32_t>(adaptor->size());
396			write(endian::native_to_little(count));
397			write_container(adaptor.str);
398			return *this;
399		}

200		binary_stream(binary_stream&) = delete;
201	
202		/*** Write ***/
203	
204		/**
205		 * @brief Serialises an object that provides a serialise function:
206		 * void serialise(auto& stream);
207		 * 
208		 * @param object The object to be serialised.
209		 */
210		void serialise(auto&& object) requires writeable<buf_type> {
211			stream_write_adaptor adaptor(*this);
212			object.serialise(adaptor);
213		}
214	
215		/**
216		 * @brief Serialises an object that provides a serialise function:
217		 * void serialise(auto& stream);
218		 * 
219		 * @param data The object to be serialised.
220		 * 
221		 * @return Reference to the current stream.
222		 */
223		template<typename T>
224		requires has_serialise<T, binary_stream>
225		binary_stream& operator<<(T& data) requires writeable<buf_type> {
226			serialise(data);
227			return *this;
228		}
